            prompt.push_str(cat);
            prompt.push('/');
            prompt.push_str(imp);
            prompt.push_str("] ");
            prompt.push_str(&e.title);
            prompt.push_str(" (");
            prompt.push_str(&e.feed);
            prompt.push_str("): ");
